// Snapshot builtAt is a Pacific wall clock (yyyy-MM-dd HH:mm), generated by
// portal-refresh/common.ts in America/Los_Angeles. It is not a UTC instant.
// Validate the stored calendar fields without letting the host/browser timezone
// reinterpret them, and never substitute the page-visit time or records.asOf.
function calendarDay(value: string): boolean {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const [, y, m, d] = match.map(Number);
  const leap = y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return y > 0 && m >= 1 && m <= 12 && d >= 1 && d <= days[m - 1];
}

export function dashboardDateLabels(snapshot: { builtAt?: unknown; asOf?: unknown }): { refreshed: string; source: string } {
  const builtAt = typeof snapshot.builtAt === "string" ? snapshot.builtAt.trim() : "";
  const asOf = typeof snapshot.asOf === "string" ? snapshot.asOf.trim() : "";
  const clock = /^(\d{4}-\d{2}-\d{2}) (\d{2}):(\d{2})$/.exec(builtAt);
  const validBuild = clock && calendarDay(clock[1]) && Number(clock[2]) < 24 && Number(clock[3]) < 60;
  return {
    refreshed: validBuild ? `Dashboard refreshed ${builtAt} Pacific` : "Dashboard refresh time unavailable",
    source: calendarDay(asOf) ? `Source data as of ${asOf}` : "Source data date unavailable",
  };
}
